-- Two CRMs. Both carry the group-wide CUSTOMER_NUMBER for the same real customer.
CREATE TABLE CRM_EU_CUSTOMER (
    CUSTOMER_NUMBER NUMBER(38,0)  NOT NULL,
    REGION_CODE     VARCHAR(4)    NOT NULL,
    FULL_NAME       VARCHAR(200)  NOT NULL,
    EMAIL           VARCHAR(255),
    CREDIT_LIMIT    NUMBER(12,2),
    UPDATED_AT      TIMESTAMP_NTZ NOT NULL,
    PRIMARY KEY (CUSTOMER_NUMBER, REGION_CODE)
);

CREATE TABLE CRM_US_CUSTOMER (
    CUSTOMER_NUMBER NUMBER(38,0)  NOT NULL PRIMARY KEY,
    FULL_NAME       VARCHAR(200)  NOT NULL,
    EMAIL           VARCHAR(255),
    CREDIT_LIMIT    NUMBER(12,2),
    UPDATED_AT      TIMESTAMP_NTZ NOT NULL
);
